def dn_domain(dn):
    return ".".join(p[3:] for p in dn.split(",") if p.upper().startswith("DC="))

print(dn_domain("CN=kim,OU=Eng,DC=kr,DC=corp,DC=example,DC=com"))  # kr.corp.example.com
print(dn_domain("CN=lee,OU=Ops,DC=us,DC=corp,DC=example,DC=com"))  # us.corp.example.com

def srv_names(domain, site):
    return [f"_ldap._tcp.{site}._sites.dc._msdcs.{domain}",
            f"_ldap._tcp.dc._msdcs.{domain}",
            f"_kerberos._tcp.{site}._sites.dc._msdcs.{domain}"]

for n in srv_names("kr.corp.example.com", "Seoul"):
    print(n)
