from datetime import datetime, timedelta, timezone

def filetime(ft):
    return datetime(1601, 1, 1, tzinfo=timezone.utc) + timedelta(microseconds=ft // 10)

print(filetime(134000000000000000))  # 2025-08-18 14:13:20+00:00

UAC = {0x2: "ACCOUNTDISABLE", 0x200: "NORMAL_ACCOUNT",
       0x10000: "DONT_EXPIRE_PASSWORD", 0x400000: "DONT_REQ_PREAUTH"}

def uac(v):
    return [n for b, n in UAC.items() if v & b]

for v in (512, 514, 66048, 4194816):
    print(v, uac(v))
# 512 ['NORMAL_ACCOUNT']
# 514 ['ACCOUNTDISABLE', 'NORMAL_ACCOUNT']
# 66048 ['NORMAL_ACCOUNT', 'DONT_EXPIRE_PASSWORD']
# 4194816 ['NORMAL_ACCOUNT', 'DONT_REQ_PREAUTH']

