    ("lee", ["Eng"], 4194816, 1),
]
for sam, groups, uac, idle in accounts:
    f = []
    if PRIV & set(groups):
        if uac & 0x10000: f.append("특권 계정 비밀번호 무기한")
        if idle > 90: f.append("특권 계정 90일 넘게 미사용")
        if uac & 0x2: f.append("꺼진 계정이 특권 그룹에 남음")
    if uac & 0x400000: f.append("사전 인증 꺼짐(AS-REP 로스팅 노출)")
    print(sam, f or "OK")
